param([Parameter(Mandatory=$true)][string]$Dir)
$ErrorActionPreference='Stop';$existing=@(Get-CimInstance Win32_Process -Filter "Name='WINWORD.EXE'"|ForEach-Object{[int]$_.ProcessId});$owned=@();$w=New-Object -ComObject Word.Application;$w.Visible=$false;$w.DisplayAlerts=0
try{$d=$w.Documents.Add();$owned=@(Get-CimInstance Win32_Process -Filter "Name='WINWORD.EXE'"|Where-Object{[int]$_.ProcessId -notin $existing}|ForEach-Object{[int]$_.ProcessId});if(-not $owned.Count){throw 'Word COM PID missing'};$d.Content.Text='Alpha beta gamma';$d.TrackRevisions=$true;$r=$d.Range($d.Content.End-1,$d.Content.End-1);$r.Text=' added';$b=$d.Range($d.Content.Start+6,$d.Content.Start+10);$b.Delete()|Out-Null;$d.SaveAs2("$Dir\word_track_changes_t8_new.docx",16);$before=@();foreach($rev in $d.Revisions){$before+=('{0}|{1}|{2}' -f [int]$rev.Type,$rev.Author,($rev.Range.Text -replace '[\r\a]',''))};Write-Output ("Word pending revisions={0}; {1}" -f $d.Revisions.Count,($before -join '; '));$d.Close(0)
 foreach($name in @('word_track_changes_t8_new.docx','app_track_changes_t8_new.docx')){$d=$w.Documents.Open("$Dir\$name",$false,$true);try{$rows=@();foreach($rev in $d.Revisions){$rows+=('{0}|{1}|{2}' -f [int]$rev.Type,$rev.Author,($rev.Range.Text -replace '[\r\a]',''))};Write-Output ("{0}: revisions={1}; {2}" -f $name,$d.Revisions.Count,($rows -join '; '))}finally{$d.Close(0)}}
}finally{if($w){$w.Quit();[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($w)};$owned=@($owned+@(Get-CimInstance Win32_Process -Filter "Name='WINWORD.EXE'"|Where-Object{[int]$_.ProcessId -notin $existing}|ForEach-Object{[int]$_.ProcessId})|Select-Object -Unique);foreach($ownedPid in $owned){$p=Get-Process -Id $ownedPid -ErrorAction SilentlyContinue;if($p){$p|Wait-Process -Timeout 3 -ErrorAction SilentlyContinue};if(Get-Process -Id $ownedPid -ErrorAction SilentlyContinue){Stop-Process -Id $ownedPid -Force -ErrorAction SilentlyContinue}}}
